/**
 * Pins the JDK that Gradle runs under.
 *
 * Android Studio bundles its own JBR and `~/.zshrc` commonly points JAVA_HOME at
 * it. That JBR is now JDK 25, and AGP's CMake configure step calls a method JDK 24+
 * restricts, so every native build dies with:
 *
 *   Execution failed for task ':react-native-worklets:configureCMakeDebug[arm64-v8a]'
 *   > WARNING: A restricted method in java.lang.System has been called
 *
 * The message names no file and no fix, which makes it expensive to rediscover. So
 * the working JDK is recorded here: `android/` is gitignored and regenerated by
 * prebuild, and a hand-edit of gradle.properties does not survive that.
 *
 * AEGIS_JDK_HOME overrides the default, for a machine that keeps its JDK elsewhere
 * or a CI image that already provides one. An absent JDK is left alone rather than
 * pinned to a path that does not exist — Gradle's own JAVA_HOME error is clearer
 * than one about a bad `org.gradle.java.home`.
 */
const fs = require('fs');
const { withGradleProperties } = require('expo/config-plugins');

const KEY = 'org.gradle.java.home';
const DEFAULT_JDK = '/opt/homebrew/opt/openjdk@21/libexec/openjdk.jdk/Contents/Home';

const withPinnedJdk = (config) => {
  const home = process.env.AEGIS_JDK_HOME ?? DEFAULT_JDK;

  if (!fs.existsSync(home)) {
    console.warn(
      `[with-pinned-jdk] ${home} not found, leaving Gradle on JAVA_HOME. ` +
        `Native builds need JDK 21: brew install openjdk@21`,
    );
    return config;
  }

  return withGradleProperties(config, (cfg) => {
    // Replace rather than append: prebuild can run against properties this plugin
    // already wrote, and two values for one key is a silent coin toss.
    cfg.modResults = cfg.modResults.filter(
      (item) => !(item.type === 'property' && item.key === KEY),
    );
    cfg.modResults.push({ type: 'property', key: KEY, value: home });
    return cfg;
  });
};

module.exports = withPinnedJdk;
